mapper.select:
SELECT ROLE_NAME
FROM USER_ROLES
WHERE USER_ID = #{userId}

mapper.update:
UPDATE USERS
SET 
    USER_NAME = #{userName},
    PHONE     = #{phone, jdbcType=VARCHAR},
    EMAIL     = #{email, jdbcType=VARCHAR},
    ENABLED   = #{enabled}

    , USER_PW  = #{userPw}

WHERE USER_ID = #{userId}
